#include <stdint.h>

#define RCC_AHB1ENR (*(volatile uint32_t*)0x40023830)
#define RCC_APB1ENR (*(volatile uint32_t*)0x40023840)
#define GPIOA_MODER (*(volatile uint32_t*)0x40020000)
#define GPIOA_ODR   (*(volatile uint32_t*)0x40020014)
#define GPIOA_AFRL  (*(volatile uint32_t*)0x40020020)
#define USART2_SR   (*(volatile uint32_t*)0x40004400)
#define USART2_DR   (*(volatile uint32_t*)0x40004404)
#define USART2_BRR  (*(volatile uint32_t*)0x40004408)
#define USART2_CR1  (*(volatile uint32_t*)0x4000440C)
#define SYST_CTRL   (*(volatile uint32_t*)0xE000E010)
#define SYST_LOAD   (*(volatile uint32_t*)0xE000E014)
#define SYST_VAL    (*(volatile uint32_t*)0xE000E018)

void uart_send_char(char c)
{
    while (!(USART2_SR & (1<<7)));
    USART2_DR = c;
}

void uart_send_string(const char *s)
{
    while (*s) uart_send_char(*s++);
}

void delay_ms(uint32_t ms)
{
    SYST_LOAD = 16000 - 1;            // 16000 ticks = 1 ms at 16 MHz
    SYST_VAL  = 0;                    // clear the counter
    SYST_CTRL = (1<<0) | (1<<2);      // enable + CPU clock, no interrupt

    while (ms--)
        while (!(SYST_CTRL & (1<<16)));   // wait for the 1 ms flag (reading clears it)

    SYST_CTRL = 0;                    // stop
}
void uart_send_int(int32_t n)
{
    char buf[11];
    int i = 0;
    uint32_t u = (uint32_t)n;

    if (n < 0) {
        uart_send_char('-');
        u = 0 - u;                    // make it positive
    }
    if (u == 0) {
        uart_send_char('0');
        return;
    }
    while (u > 0) {
        buf[i++] = '0' + (u % 10);    // last digit, as a character
        u /= 10;                      // drop the last digit
    }
    while (i--)
        uart_send_char(buf[i]);       // digits came out backwards, so send in reverse
}

void uart_send_hex8(uint8_t v)
{
    const char *h = "0123456789ABCDEF";
    uart_send_string("0x");
    uart_send_char(h[v >> 4]);        // high 4 bits
    uart_send_char(h[v & 0xF]);       // low 4 bits
}


int main(void)
{
    RCC_AHB1ENR |= (1<<0);
    RCC_APB1ENR |= (1<<17);

    GPIOA_MODER &= ~(3<<(5*2));       // PA5 output
    GPIOA_MODER |=  (1<<(5*2));

    GPIOA_MODER &= ~(3<<(2*2));       // PA2 alternate function
    GPIOA_MODER |=  (2<<(2*2));
    GPIOA_AFRL  &= ~(0xF<<(2*4));
    GPIOA_AFRL  |=  (7<<(2*4));

    USART2_BRR  = 0x008B;
    USART2_CR1 |= (1<<3) | (1<<13);   // TE + UE

    int32_t count = -3;

    while (1)
    {
        uart_send_string("count = ");
        uart_send_int(count);
        uart_send_string("  hex of low byte = ");
        uart_send_hex8((uint8_t)count);
        uart_send_string("\r\n");

        count++;
        delay_ms(500);
    }
}
